import json,glob,collections,re,sys
for repo in sys.argv[1:]:
    cmds=[]; tools=collections.Counter()
    for f in glob.glob(f'{repo}/docs/agent-history/*.events.jsonl'):
        for l in open(f):
            try: e=json.loads(l)
            except: continue
            if e.get('kind') not in ('tool_call','tool_start','tool_use','tool_result','tool') and not e.get('tool'): continue
            t=e.get('tool'); 
            if not t: continue
            inp=e.get('input') or {}
            if isinstance(inp,dict) and 'command' in inp and t=='Bash':
                cmds.append(inp['command'])
            tools[t]+=1
    cmds=list(dict.fromkeys(cmds))
    print('=====',repo,len(cmds),'bash cmds')
    print(tools.most_common(30))
    mk=collections.Counter(); sc=collections.Counter(); isc=collections.Counter()
    for c in cmds:
        for m in re.findall(r'\bmake\s+(?:-C\s+\S+\s+)?([a-z][\w-]*)',c): mk[m]+=1
        for m in re.findall(r'scripts/([\w./-]+)',c): sc[m.split('/')[0] if '/' in m else m]+=1
        for m in re.findall(r'isuscope(?:\s+--project\s+\S+)?\s+([a-z_-]+)(?:\s+([a-z_-]+))?',c): isc[' '.join(x for x in m if x)]+=1
    print('MAKE',mk.most_common()); print('SCRIPTS',sc.most_common()); print('ISUSCOPE',isc.most_common())
EOF
