        manifest = next(iter(glob.glob(str(root / 'isuscope-data/runs' / row['id'] / 'run.json'))), None)
        row['after_seconds'] = None
        if manifest:
            benchmark = json.loads(Path(manifest).read_text()).get('benchmark') or {}
