#[derive(Debug, Serialize)]
pub struct BriefChange {
    pub id: String,
    pub description: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub target: Option<String>,
    /// 最新の判断。まだ判断していない変更では出さない。
    #[serde(skip_serializing_if = "Option::is_none")]
    pub status: Option<&'static str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub decided_at: Option<String>,
    /// 理由が`latest_analysis.body`と同じ文章なら出さず、`reason_same_as_analysis`を立てる。
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reason: Option<String>,
    #[serde(skip_serializing_if = "std::ops::Not::not")]
    pub reason_same_as_analysis: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub revisit: Option<String>,
    /// 判断の根拠にしたrun。`短縮ID commit先頭12桁`、未commitの変更があれば` dirty`を付ける。
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub evidence: Vec<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub full_text: Option<String>,
}

pub fn review(review: crate::changes::RunReview) -> BriefReview {
    let short = |id: &str| crate::runner::short_id(id).to_owned();
    let analysis_body = review
        .latest_analysis
        .as_ref()
        .map(|analysis| analysis.body.clone());
    let latest_analysis = review.latest_analysis.map(|analysis| {
        let (body, cut) = excerpt(&analysis.body);
        BriefAnalysis {
            verdict: analysis.verdict,
            base: analysis.base_run_id.as_deref().map(short),
            body,
            full_text: cut.then(|| {
                format!(
                    "isuscope sql \"SELECT body FROM run_analyses WHERE id='{}'\"",
                    analysis.id
                )
            }),
        }
    });
    let comparison = review.comparison.map(|comparison| BriefComparison {
        base: short(&comparison.base_run_id),
        base_source: "analysis",
        score_base: comparison.score.base,
        score: comparison.score.candidate,
        score_delta: comparison.score.delta,
        score_delta_percent: comparison.score.delta_percent,
        conditions: comparison.conditions,
    });
    let changes = review
        .changes
        .into_iter()
        .map(|summary| {
            let change = summary.change;
            let (description, mut cut) = excerpt(&change.description);
            let decision = summary.latest_decision;
            let same = decision
                .as_ref()
                .is_some_and(|decision| Some(&decision.reason) == analysis_body.as_ref());
            let reason = decision.as_ref().filter(|_| !same).map(|decision| {
                let (reason, reason_cut) = excerpt(&decision.reason);
                cut |= reason_cut;
                reason
            });
            BriefChange {
                full_text: cut.then(|| format!("isuscope change show {}", change.id)),
                id: change.id,
                description,
                target: change.target,
                status: decision.as_ref().map(|decision| decision.status.as_str()),
                decided_at: decision
                    .as_ref()
                    .map(|decision| crate::model::display_time(decision.created_at)),
                reason,
                reason_same_as_analysis: same,
                revisit: decision
                    .as_ref()
                    .and_then(|decision| decision.revisit.clone()),
                evidence: decision
                    .map(|decision| {
                        decision
                            .evidence
                            .iter()
                            .map(crate::changes::evidence_label)
                            .collect()
                    })
                    .unwrap_or_default(),
            }
        })
        .collect();
    BriefReview {
        latest_analysis,
        comparison,
        changes: section(changes, REVIEW_CHANGES),
    }
}

/// `run`より前に始まったrunのうち、終わっていてベンチを始めた最も新しいもの。`prepare_command`で
/// 止まったrunや、同じ構成として断ったrunは比較元にしない。briefと`analyze`の既定の比較元。
pub fn previous_run(
    store: &crate::storage::Store,
    run: &RunManifest,
) -> anyhow::Result<Option<RunManifest>> {
    let mut statement = store.connection.prepare(
        "SELECT id FROM runs WHERE id != ?1 AND state != 'running'
           AND started_at < (SELECT started_at FROM runs WHERE id = ?1)
         ORDER BY started_at DESC LIMIT 200",
    )?;
    let ids = statement
        .query_map([&run.id], |row| row.get::<_, String>(0))?
        .collect::<rusqlite::Result<Vec<_>>>()?;
    for id in ids {
        let Ok(manifest) = store.load(&id) else {
            continue;
        };
        if manifest.benchmark.mode != "not-started" && manifest.benchmark.started_at.is_some() {
            return Ok(Some(manifest));
        }
    }
    Ok(None)
}

/// `review.comparison`を付ける。比較元を決めてあれば（`base`）それと比べ、分析の比較元より
/// 優先する。決めていなければ分析の比較元、それも無ければ直前のrun（[`previous_run`]）と比べる。
/// 比較の前提は分析の比較元と同じ方法で求める（比較元だけを差し替えた写しを`run_review`へ渡す）。
pub fn attach_comparison(
    brief: &mut BriefOutput,
    store: &crate::storage::Store,
    base: Option<&str>,
) -> anyhow::Result<()> {
    let has_analysis_base = brief
        .review
        .as_ref()
        .is_some_and(|review| review.comparison.is_some());
    let run = store.load(&brief.summary.id)?;
    let (base_id, source) = match base {
        Some(base) => (base.to_owned(), "run_base"),
        None if has_analysis_base => return Ok(()),
        None => match previous_run(store, &run)? {
            Some(previous) => (previous.id, "previous_run"),
            None => return Ok(()),
        },
    };
    let Some(comparison) = compare_with(store, run, base_id, source)? else {
        return Ok(());
    };
    match brief.review.as_mut() {
        Some(review) => review.comparison = Some(comparison),
        None => {
            brief.review = Some(BriefReview {
                latest_analysis: None,
                comparison: Some(comparison),
                changes: section(Vec::new(), REVIEW_CHANGES),
            })
        }
    }
    Ok(())
}

fn compare_with(
    store: &crate::storage::Store,
    run: RunManifest,
    base_id: String,
    source: &'static str,
) -> anyhow::Result<Option<BriefComparison>> {
    let mut probe = run;
    probe.analyses = vec![crate::model::RunAnalysis {
        id: String::new(),
        created_at: chrono::Utc::now(),
        verdict: crate::model::AnalysisVerdict::Skipped,
        body: String::new(),
        base_run_id: Some(base_id),
    }];
    Ok(store
        .run_review(&probe)?
        .comparison
        .map(|comparison| BriefComparison {
            base: crate::runner::short_id(&comparison.base_run_id).to_owned(),
            base_source: source,
            score_base: comparison.score.base,
            score: comparison.score.candidate,
            score_delta: comparison.score.delta,
            score_delta_percent: comparison.score.delta_percent,
            conditions: comparison.conditions,
        }))
}

/// 比較元を決めていないrunに、比較元の候補として示す事実：最後に採用した変更のrunと、直前のrun。
#[derive(Debug)]
pub struct BaseCandidates {
    /// 最新の判断が`accepted`の変更が根拠にした、最も新しいrunとそのscore。
    pub accepted: Option<(String, Option<i64>)>,
    /// 直前のrun（[`previous_run`]）、score、最新の分析の判定（無ければ分析の状態）。
    pub previous: Option<(String, Option<i64>, String)>,
}

impl std::fmt::Display for BaseCandidates {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let score = |score: &Option<i64>| score.map_or("-".into(), |score| thousands(score as f64));
        let mut parts = Vec::new();
        if let Some((id, value)) = &self.accepted {
            parts.push(format!(
                "last accepted {} {}",
                crate::runner::short_id(id),
                score(value)
            ));
        }
        if let Some((id, value, verdict)) = &self.previous {
            parts.push(format!(
                "previous {} {} ({verdict})",
                crate::runner::short_id(id),
                score(value)
            ));
        }
        write!(f, "candidates: {}", parts.join("; "))
    }
}

/// `run`より前のrunから比較元の候補を探す。どちらも無ければ`None`（最初のrun）。
pub fn base_candidates(
    store: &crate::storage::Store,
    run: &RunManifest,
) -> anyhow::Result<Option<BaseCandidates>> {
    use rusqlite::OptionalExtension;
    let accepted = store
        .connection
        .query_row(
            "SELECT r.id, r.score FROM change_decision_runs dr
               JOIN change_decisions d ON d.id = dr.decision_id
               JOIN runs r ON r.id = dr.run_id
              WHERE d.status = 'accepted'
                AND d.created_at = (SELECT MAX(created_at) FROM change_decisions WHERE change_id = d.change_id)
                AND r.id != ?1 AND r.started_at < ?2
              ORDER BY r.started_at DESC LIMIT 1",
            rusqlite::params![run.id, run.started_at.to_rfc3339()],
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, Option<i64>>(1)?)),
        )
        .optional()?;
    let previous = previous_run(store, run)?.map(|previous| {
        let verdict = previous
            .analyses
            .last()
            .map(|analysis| analysis.verdict.as_str().to_owned())
            .unwrap_or_else(|| previous.analysis_status.as_str().replace('_', " "));
        (previous.id, previous.benchmark.score, verdict)
    });
    if accepted.is_none() && previous.is_none() {
        return Ok(None);
    }
    Ok(Some(BaseCandidates { accepted, previous }))
}

/// 同じ構成を2回以上測ってPASSした組のうち、最も新しく測った組。同じ構成とは、`config_key`が
/// 等しいか、`--repeat`で前のrunと同じ構成を測り直したもの（`repeat_base_run_id`）。`run`より後に
/// 始まったrunは入れない。scoreの振れ幅の目安で、採否の閾値ではない。
#[derive(Debug, Clone, PartialEq)]
pub struct Spread {
    pub commit: Option<String>,
    pub runs: usize,
    pub min: i64,
    pub max: i64,
}

pub fn latest_spread(
    store: &crate::storage::Store,
    run: &RunManifest,
) -> anyhow::Result<Option<Spread>> {
    struct Row {
        id: String,
        config_key: Option<String>,
        repeats: Option<String>,
        commit: Option<String>,
        score: i64,
    }
    let mut statement = store.connection.prepare(
        "SELECT id, config_key, CASE WHEN repeat_reason IS NOT NULL THEN repeat_base_run_id END,
                commit_hash, score
           FROM runs
          WHERE passed = 1 AND state = 'complete' AND score IS NOT NULL AND started_at <= ?1
          ORDER BY started_at, id",
    )?;
    let rows = statement
        .query_map([run.started_at.to_rfc3339()], |row| {
            Ok(Row {
                id: row.get(0)?,
                config_key: row.get(1)?,
                repeats: row.get(2)?,
                commit: row.get(3)?,
                score: row.get(4)?,
            })
        })?
        .collect::<rusqlite::Result<Vec<_>>>()?;
    // 組を、最初に測ったrunの位置で表す。
    let mut group = Vec::<usize>::with_capacity(rows.len());
    let mut by_key = BTreeMap::<&str, usize>::new();
    let mut by_id = BTreeMap::<&str, usize>::new();
    for (position, row) in rows.iter().enumerate() {
        let same = row
            .repeats
            .as_deref()
            .and_then(|base| by_id.get(base).map(|index| group[*index]))
            .or_else(|| {
                row.config_key
                    .as_deref()
                    .and_then(|key| by_key.get(key).map(|index| group[*index]))
            })
            .unwrap_or(position);
        group.push(same);
        by_id.insert(&row.id, position);
        if let Some(key) = row.config_key.as_deref() {
            by_key.insert(key, position);
        }
    }
    let mut groups = BTreeMap::<usize, (usize, Vec<usize>)>::new();
    for (position, first) in group.iter().enumerate() {
        let entry = groups.entry(*first).or_insert((position, Vec::new()));
        entry.0 = position;
        entry.1.push(position);
    }
    Ok(groups
        .into_values()
        .filter(|(_, members)| members.len() >= 2)
        .max_by_key(|(last, _)| *last)
        .map(|(last, members)| {
            let scores = members.iter().map(|index| rows[*index].score);
            Spread {
                commit: rows[last].commit.clone(),
                runs: members.len(),
                min: scores.clone().min().unwrap_or_default(),
                max: scores.max().unwrap_or_default(),
            }
        }))
}

/// 3桁ごとにcommaを入れた整数。
pub fn thousands(value: f64) -> String {
    let rounded = value.round() as i64;
    let digits = rounded.unsigned_abs().to_string();
    let mut out = String::new();
    for (index, digit) in digits.chars().enumerate() {
        if index > 0 && (digits.len() - index).is_multiple_of(3) {
            out.push(',');
        }
        out.push(digit);
    }
    if rounded < 0 { format!("-{out}") } else { out }
}

fn excerpt(text: &str) -> (String, bool) {
