            .unwrap()
            .with_timezone(&chrono::Utc);
        let at = |seconds: i64| start + chrono::Duration::seconds(seconds);
        let metric = |name: &str, value: f64, second: i64, labels: &[(&str, &str)]| Metric {
            name: name.into(),
