                .collect(),
        };
        let failed = [("target", "payment"), ("outcome", "502")];
        let ok = [("target", "payment"), ("outcome", "204")];
        let store = [("lock", "store")];
        let metrics = [
            // initializeの間（区間の外）は足さない。
            metric("app.call.count", 100.0, 0, &failed),
            metric("app.call.count", 7.0, 2, &failed),
