fn isuscope(project: &std::path::Path, args: &[&str]) -> String {
    let output = Command::new(env!("CARGO_BIN_EXE_isuscope"))
        .args(args)
        .current_dir(project)
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "{args:?}: {}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8(output.stdout).unwrap()
}

fn latest(project: &std::path::Path) -> String {
    let list = parsed(isuscope(project, &["list", "--limit", "1"]).as_bytes()).unwrap();
    list["runs"]["rows"][0]["run"].as_str().unwrap().to_owned()
}

/// 1回目を測って採用し、比較元を決めずに2回目を測る。
fn two_runs(project: &std::path::Path) -> (String, String, String) {
    isuscope(project, &["run", "--hypothesis", "first"]);
    let first = latest(project);
    isuscope(
        project,
        &[
            "analyze",
            &first,
            "supported",
            "--analysis",
            "採用",
            "--change",
            "first-change",
            "--decision",
            "accepted",
        ],
    );
    let second_run = isuscope(
        project,
        &["run", "--hypothesis", "second", "--repeat", "measure again"],
    );
    (first, latest(project), second_run)
}

#[test]
fn without_a_base_run_and_brief_ask_for_one_and_show_no_changes() {
    let project = project();
    let (first, second, second_run) = two_runs(project.path());
    // 始めた時点で、比較元を決めるよう求め、候補を事実で並べる。
    assert!(
        second_run.contains(&format!(
            "base not set: decide the comparison base during the benchmark and set it with `isuscope base {second} <run>`"
        )),
        "{second_run}"
    );
    assert!(
        second_run.contains(&format!(
            "candidates: last accepted {first} 1,000; previous {first} 1,000 (supported)"
        )),
        "{second_run}"
    );
    let brief = isuscope(project.path(), &["brief", &second]);
    assert!(
        brief.starts_with(&format!(
            "{second} PASS 2,000  base not set: set it with `isuscope base {second} <run>`"
        )),
        "{brief}"
    );
    // 直前のrunで代えて差を出さない。
    assert!(!brief.contains("(base"), "{brief}");
    assert!(!brief.contains("%)"), "{brief}");
}

#[test]
fn a_base_set_later_gives_counts_shares_and_changes_matched_by_name() {
    let project = project();
    let (first, second, _) = two_runs(project.path());
    let set = isuscope(project.path(), &["base", &second, &first]);
    assert!(
        set.contains(&format!("base      {first} for run {second}")),
        "{set}"
    );
    let brief = isuscope(project.path(), &["brief", &second]);
    let line = |prefix: &str| {
        brief
            .lines()
            .find(|line| line.trim_start().starts_with(prefix))
            .unwrap_or_else(|| panic!("no `{prefix}` line in\n{brief}"))
            .to_owned()
    };
    assert!(
        brief.starts_with(&format!(
            "{second} PASS 2,000  base {first} 1,000 (+100.0%)"
        )),
        "{brief}"
    );
    // 件数は警告の行の数で、残した実例の数（5）ではない。比較元に無かったcategoryには実例を1つ。
    assert!(
        line("bench").contains("warnings 8: CODE=30 8 (base 3), CODE=24 1 (base 0)"),
        "{brief}"
    );
    assert!(
        line("new CODE=24").contains("sales are larger than expected"),
        "{brief}"
    );
    assert_eq!(
        line("counts"),
        "counts   ride created 200 (+100.0%)  ride COMPLETED 160 (+100.0%)"
    );
    // 順位が入れ替わっても、比較元の値は同じrouteのもの。/pollは順位に入れず別の行。
    let http = brief
        .lines()
        .skip_while(|line| !line.starts_with("http"))
        .collect::<Vec<_>>();
    assert!(
        http[1].contains("GET /b") && http[1].contains("8 (1)"),
        "{brief}"
    );
    assert!(
        http[2].contains("GET /a") && http[2].contains("2 (9)"),
        "{brief}"
    );
    assert!(
        !http[1..3].iter().any(|line| line.contains("/poll")),
        "{brief}"
    );
    assert!(line("polling").contains("GET /poll 20 5,000ms"), "{brief}");
    // 割合は呼び先の全ての結果に対するもの。
    assert!(
        line("app").contains("calls payment 100: 204 60%, 502 30%, 500 10% (avg 10ms)"),
        "{brief}"
    );
    assert!(brief.len() < 2500, "{} bytes:\n{brief}", brief.len());
    // `analyze`は決めた比較元を既定にする。
    let analyzed = isuscope(
        project.path(),
        &["analyze", &second, "supported", "--analysis", "比較した"],
    );
    assert!(
        analyzed.contains(&format!("base      {first} (run base)")),
        "{analyzed}"
    );
    // JSONは今までの形のまま、決めた比較元と比べる。
    let json = parsed(isuscope(project.path(), &["brief", &second, "--json"]).as_bytes()).unwrap();
    assert_eq!(json["base"], first.as_str());
    assert_eq!(json["review"]["comparison"]["base"], first.as_str());
    assert_eq!(json["review"]["comparison"]["base_source"], "run_base");
}

#[test]
fn run_base_is_recorded_and_running_names_the_run_in_progress() {
    let project = project();
    isuscope(project.path(), &["run", "--hypothesis", "first"]);
    let first = latest(project.path());
    isuscope(
        project.path(),
        &["analyze", &first, "skipped", "--analysis", "基準"],
    );

    // `run --base`は始める前に比較元を確かめて記録する。
    let output = isuscope(
        project.path(),
        &[
            "run",
            "--hypothesis",
            "second",
            "--repeat",
            "again",
            "--base",
            &first,
        ],
    );
    assert!(output.contains(&format!("base      {first}")), "{output}");
    assert!(!output.contains("base not set"), "{output}");
    let second = latest(project.path());
    assert!(
        isuscope(project.path(), &["brief", &second])
            .starts_with(&format!("{second} PASS 2,000  base {first} 1,000")),
    );
    isuscope(
        project.path(),
        &["analyze", &second, "skipped", "--analysis", "次"],
    );

    // ベンチの間に`isuscope base running <run>`で決めると、そのrunの比較元になる。
    let mut child = Command::new(env!("CARGO_BIN_EXE_isuscope"))
        .args(["run", "--hypothesis", "third", "--repeat", "again"])
        .current_dir(project.path())
        .stdout(std::process::Stdio::piped())
        .spawn()
        .unwrap();
    let mut reader = BufReader::new(child.stdout.take().unwrap());
    let mut seen = String::new();
    loop {
        let mut line = String::new();
        assert!(reader.read_line(&mut line).unwrap() > 0, "{seen}");
        seen.push_str(&line);
        if line.starts_with("base not set") {
            break;
        }
    }
    isuscope(project.path(), &["base", "running", &first]);
    std::io::copy(&mut reader, &mut std::io::sink()).unwrap();
    assert!(child.wait().unwrap().success());
    let third = latest(project.path());
    assert!(
        isuscope(project.path(), &["brief", &third])
            .starts_with(&format!("{third} PASS 3,000  base {first} 1,000")),
    );
    // 比較元はrun.jsonにも残る（indexを作り直しても消えない）。
    let manifest: serde_json::Value = serde_json::from_slice(
        &fs::read(
            project
                .path()
                .join(".isuscope/runs")
                .join(full_run_id(&project.path().join(".isuscope/runs"), &third))
                .join("run.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert!(
        manifest["base_run_id"].as_str().unwrap().ends_with(&first),
        "{manifest}"
    );
    for name in [
        "isuscope.sqlite3",
        "isuscope.sqlite3-wal",
        "isuscope.sqlite3-shm",
    ] {
        let _ = fs::remove_file(project.path().join(".isuscope").join(name));
    }
    assert!(
        isuscope(project.path(), &["brief", &third])
            .starts_with(&format!("{third} PASS 3,000  base {first} 1,000")),
    );

    // 走っているrunが無ければ、`running`はそう言って止まる。
    let error = Command::new(env!("CARGO_BIN_EXE_isuscope"))
        .args(["base", "running", &first])
        .current_dir(project.path())
        .output()
        .unwrap();
    assert!(!error.status.success());
    assert!(String::from_utf8_lossy(&error.stderr).contains("no run is running"));
}

