//! 短い文のbrief。採否と次の制約を決める人が、最初に1回読んで足りるだけを、決めた比較元
//! との差と一緒に出す。行は欄ごとに決まった数だけ並べ、全欄の値は`brief --json`と`query`にある。
//!
//! 値はどれも、行を切っていないbrief（[`BriefOutput`]）と、benchmark・状態ログのmetricから
//! 求める。比較元との差は、順位の位置ではなくrouteやserviceの名前で突き合わせて出す。

use crate::{
    brief::{BaseCandidates, BriefOutput, Spread, thousands},
    config::BriefConfig,
    model::Metric,
    report::HttpRouteSummary,
};
use std::collections::BTreeMap;
use std::fmt::Write;

/// 1つのrunについて、文を組むのに使う値。
pub struct RunFacts {
    /// 行を切っていないbrief。
    pub brief: BriefOutput,
    /// `benchmark.`のmetric（警告・エラーのcategoryごとの件数、initializeの時間）。
    pub benchmark: Vec<Metric>,
    /// 状態ログの`state.transitions`と`state.lines`。
    pub states: Vec<Metric>,
}

pub struct Inputs<'a> {
    pub run: &'a RunFacts,
    /// 決めた比較元。無ければ差を出さない（直前のrunで代えない）。
    pub base: Option<&'a RunFacts>,
    pub settings: &'a BriefConfig,
    /// 比較元を決めていないときに示す候補。
    pub candidates: Option<&'a BaseCandidates>,
    pub spread: Option<&'a Spread>,
}

/// 順位の表に並べる行数。
const TOP: usize = 3;
/// 仮説の抜粋の文字数。
const HYPOTHESIS_CHARS: usize = 80;
/// 例文・logの抜粋の文字数。
const SAMPLE_CHARS: usize = 120;
/// 2番目のserviceを出すCPU（core）。どちらのrunでもこれ未満なら、無いのと同じなので省く。
const MINOR_SERVICE_CORES: f64 = 0.05;

pub fn render(inputs: &Inputs) -> String {
    let mut out = String::new();
    header(&mut out, inputs);
    bench(&mut out, inputs);
    counts(&mut out, inputs);
    nodes(&mut out, inputs);
    http(&mut out, inputs);
    sql(&mut out, inputs);
    app(&mut out, inputs);
    edge(&mut out, inputs);
    go(&mut out, inputs);
    issues(&mut out, inputs);
    out
}

fn header(out: &mut String, inputs: &Inputs) {
    let brief = &inputs.run.brief;
    let summary = &brief.summary;
    let verdict = match summary.passed {
        Some(true) => "PASS".to_owned(),
        Some(false) => "FAIL".to_owned(),
        None => summary.state.to_uppercase(),
    };
    let score = summary.score.map(|score| score as f64);
    let _ = write!(out, "{} {verdict} {}", brief.run, number(score));
    match inputs.base {
        Some(base) => {
            let base_score = base.brief.summary.score.map(|score| score as f64);
            let _ = writeln!(
                out,
                "  base {} {}{}",
                base.brief.run,
                number(base_score),
                change(score, base_score)
                    .map(|change| format!(" ({change})"))
                    .unwrap_or_default()
            );
        }
        None => {
            let _ = writeln!(
                out,
                "  base not set: set it with `isuscope base {} <run>` (no changes shown)",
                brief.run
            );
            if let Some(candidates) = inputs.candidates {
                let _ = writeln!(out, "  {candidates}");
            }
        }
    }
    if let Some(spread) = inputs.spread {
        let commit = spread
            .commit
            .as_deref()
            .map(|commit| &commit[..commit.len().min(7)])
            .unwrap_or("same config");
        let _ = writeln!(
            out,
            "spread   {commit} ×{} PASS: {}–{}",
            spread.runs,
            thousands(spread.min as f64),
            thousands(spread.max as f64)
        );
    }
    let hypothesis = summary.hypothesis.split_whitespace().collect::<Vec<_>>();
    if !hypothesis.is_empty() {
        let (text, _) = crate::model::excerpt(&hypothesis.join(" "), HYPOTHESIS_CHARS);
        let _ = writeln!(out, "hyp      {text}");
    }
}

/// categoryごとの件数（`benchmark.<kind>`）と合計（`benchmark.<kind>_total`、無ければ件数の和）。
fn message_counts(metrics: &[Metric], kind: &str) -> (Option<f64>, BTreeMap<String, f64>) {
    let name = format!("benchmark.{kind}");
    let total_name = format!("benchmark.{kind}_total");
    let mut categories = BTreeMap::<String, f64>::new();
    let mut total = None;
    for metric in metrics {
        if metric.name == total_name {
            *total.get_or_insert(0.0) += metric.value;
        } else if metric.name == name {
            let category = metric
                .labels
                .get("category")
                .cloned()
                .unwrap_or_else(|| "-".into());
            *categories.entry(category).or_default() += metric.value;
        }
    }
    if total.is_none() && !categories.is_empty() {
        total = Some(categories.values().sum());
    }
    (total, categories)
}

fn bench(out: &mut String, inputs: &Inputs) {
    let run = inputs.run;
    let base = inputs.base;
    let mut parts = Vec::new();
    let mut new_categories = Vec::new();
    for kind in ["errors", "warnings"] {
        let (total, categories) = message_counts(&run.benchmark, kind);
        let base_categories = base.map(|base| message_counts(&base.benchmark, kind).1);
        let Some(total) = total else {
            continue;
        };
        let mut names = categories.keys().cloned().collect::<Vec<_>>();
        if let Some(base_categories) = &base_categories {
            names.extend(
                base_categories
                    .keys()
                    .filter(|name| !categories.contains_key(*name))
                    .cloned(),
            );
        }
        names.sort_by(|a, b| {
            let value = |name: &str| categories.get(name).copied().unwrap_or_default();
            value(b).total_cmp(&value(a)).then(a.cmp(b))
        });
        let shown = names
            .iter()
            .take(4)
            .map(|name| {
                let value = categories.get(name).copied().unwrap_or_default();
                let base_value = base_categories.as_ref().map(|base| {
                    format!(
                        " (base {})",
                        number(Some(base.get(name).copied().unwrap_or_default()))
                    )
                });
                if value > 0.0
                    && base_categories
                        .as_ref()
                        .is_some_and(|base| base.get(name).copied().unwrap_or_default() == 0.0)
                {
                    new_categories.push((kind, name.clone()));
                }
                format!(
                    "{name} {}{}",
                    number(Some(value)),
                    base_value.unwrap_or_default()
                )
            })
            .collect::<Vec<_>>();
        let more = names.len().saturating_sub(shown.len());
        let mut part = format!("{kind} {}", number(Some(total)));
        if !shown.is_empty() {
            part.push_str(": ");
            part.push_str(&shown.join(", "));
            if more > 0 {
                let _ = write!(part, ", +{more} more");
            }
        }
        parts.push(part);
    }
    if let Some(init) = run
        .benchmark
        .iter()
        .find(|metric| metric.name == "benchmark.initialize_duration")
    {
        parts.push(format!("init {}", seconds(init.value)));
    }
    if !parts.is_empty() {
        let _ = writeln!(out, "bench    {}", parts.join("; "));
    }
    let messages = &run.brief.benchmark_messages;
    if run.brief.summary.passed == Some(false) {
        let reason = messages
            .failure
            .first()
            .or_else(|| {
                messages
                    .errors
                    .first()
                    .and_then(|group| group.samples.first())
            })
            .map(|text| sample(text));
        let _ = writeln!(
            out,
            "fail     {}",
            reason.unwrap_or_else(|| "no failure message was kept".into())
        );
    }
    // 比較元に無かったcategoryだけ、実例を1つ。
    for (kind, category) in new_categories.into_iter().take(2) {
        let groups = if kind == "errors" {
            &messages.errors
        } else {
            &messages.warnings
        };
        if let Some(text) = groups
            .iter()
            .find(|group| group.category.as_deref() == Some(category.as_str()))
            .and_then(|group| group.samples.first())
        {
            let _ = writeln!(out, "  new {category}: {}", sample(text));
        }
    }
}

/// 状態ログの`kind`の作られた数（`state`無し）か、`state`に入った数。
fn state_count(metrics: &[Metric], kind: &str, state: Option<&str>) -> Option<f64> {
    let mut found = false;
    let mut total = 0.0;
    for metric in metrics
        .iter()
        .filter(|metric| metric.name == "state.transitions")
    {
        found = true;
        let label = |name: &str| metric.labels.get(name).map(String::as_str);
        if label("kind") != Some(kind) {
            continue;
        }
        let counted = match state {
            Some(state) => label("to") == Some(state),
            None => label("from") == Some(crate::states::CREATED),
        };
        if counted {
            total += metric.value;
        }
    }
    found.then_some(total)
}

fn counts(out: &mut String, inputs: &Inputs) {
    let settings = &inputs.settings.counts;
    if settings.is_empty() {
        return;
    }
    let has_log = |facts: &RunFacts| {
        facts
            .states
            .iter()
            .any(|metric| metric.name == "state.transitions")
    };
    if !has_log(inputs.run) {
        let _ = writeln!(out, "counts   no state log in this run");
        return;
    }
    let base = inputs.base.filter(|base| has_log(base));
    let items = settings
        .iter()
        .map(|count| {
            let value = state_count(&inputs.run.states, &count.kind, count.state.as_deref());
            let base_value = base
                .and_then(|base| state_count(&base.states, &count.kind, count.state.as_deref()));
            format!(
                "{} {}{}",
                count.label,
                number(value),
                change(value, base_value)
                    .map(|change| format!(" ({change})"))
                    .unwrap_or_default()
            )
        })
        .collect::<Vec<_>>();
    let _ = writeln!(out, "counts   {}", items.join("  "));
}

fn nodes(out: &mut String, inputs: &Inputs) {
    let hosts = &inputs.run.brief.hosts.items;
    if hosts.is_empty() {
        return;
    }
    let base_hosts = inputs.base.map(|base| &base.brief.hosts.items);
    let window = inputs
        .run
        .brief
        .hosts
        .window
        .as_deref()
        .map(|window| format!(" ({window})"))
        .unwrap_or_default();
    let _ = writeln!(
        out,
        "nodes{window}  busy avg/max %, busiest core %, service cores max{}, rd = run_delay cores",
        if inputs.base.is_some() { " (base)" } else { "" }
    );
    let width = hosts.iter().map(|host| host.node.len()).max().unwrap_or(0);
    for host in hosts {
        let base_host =
            base_hosts.and_then(|hosts| hosts.iter().find(|base| base.node == host.node));
        let base_cores = |service: &str| {
            base_host
                .and_then(|base| {
                    base.top_services
                        .iter()
                        .find(|candidate| candidate.service == service)
                })
                .and_then(|candidate| candidate.cpu_max_cores)
        };
        let services = host
            .top_services
            .iter()
            .take(2)
            .enumerate()
            .filter(|(index, service)| {
                *index == 0
                    || service.cpu_max_cores.unwrap_or_default() >= MINOR_SERVICE_CORES
                    || base_cores(&service.service).unwrap_or_default() >= MINOR_SERVICE_CORES
            })
            .map(|(_, service)| {
                let mut text = format!(
                    "{} {}",
                    service.service.trim_end_matches(".service"),
                    cores(service.cpu_max_cores)
                );
                if inputs.base.is_some() {
                    let _ = write!(text, " ({})", cores(base_cores(&service.service)));
                }
                if let Some(delay) = service.run_delay_avg_cores.filter(|delay| *delay >= 0.01) {
                    let _ = write!(text, " rd {delay:.2}");
                }
                text
            })
            .collect::<Vec<_>>();
        let busy = format!(
            "{}/{}",
            percent(host.cpu_busy_avg_percent),
            percent(host.cpu_busy_max_percent)
        );
        let _ = writeln!(
            out,
            "  {:width$}  {busy:<7} core {:>3}  {}",
            host.node,
            percent(host.busiest_core_max_percent),
            services.join("; "),
        );
    }
}

fn route_key(row: &HttpRouteSummary) -> String {
    format!("{} {}", row.method, row.route)
}

fn http(out: &mut String, inputs: &Inputs) {
    let brief = &inputs.run.brief;
    let rows = &brief.http.items;
    if rows.is_empty() {
        return;
    }
    let polling = &inputs.settings.polling_routes;
    let base_rows = inputs.base.map(|base| &base.brief.http.items);
    let base_row = |row: &HttpRouteSummary| {
        base_rows.and_then(|rows| {
            rows.iter()
                .find(|base| base.node == row.node && route_key(base) == route_key(row))
                .or_else(|| rows.iter().find(|base| route_key(base) == route_key(row)))
        })
    };
    let mut ranked = rows
        .iter()
        .filter(|row| !polling.contains(&route_key(row)))
        .collect::<Vec<_>>();
    ranked.sort_by(|a, b| {
        b.total_ms
            .unwrap_or_default()
            .total_cmp(&a.total_ms.unwrap_or_default())
    });
    ranked.truncate(TOP);
    let one_node = rows.iter().all(|row| row.node == rows[0].node);
    let label = |row: &HttpRouteSummary| {
        let route = shorten(&route_key(row), 34);
        if one_node {
            route
        } else {
            format!("{} {route}", row.node)
        }
    };
    let width = ranked
        .iter()
        .map(|row| label(row).chars().count())
        .max()
        .unwrap_or(0);
    let _ = writeln!(
        out,
        "http{}  by total time{}   count  avg ms{}  p95",
        if one_node {
            format!(" {}", rows[0].node)
        } else {
            String::new()
        },
        if polling.is_empty() {
            ""
        } else {
            ", polling apart"
        },
        if inputs.base.is_some() { " (base)" } else { "" }
    );
    for row in ranked {
        let mut average = milliseconds(row.avg_ms);
        if inputs.base.is_some() {
            let _ = write!(
                average,
                " ({})",
                milliseconds(base_row(row).and_then(|base| base.avg_ms))
            );
        }
        let name = label(row);
        let pad = width.saturating_sub(name.chars().count());
        let _ = writeln!(
            out,
            "  {name}{:pad$}  {:>9}  {average}  {}",
            "",
            number(Some(row.count)),
            milliseconds(row.p95_ms),
        );
    }
    let held = polling
        .iter()
        .filter_map(|route| rows.iter().find(|row| route_key(row) == *route))
        .map(|row| {
            format!(
                "{} {} {}ms",
                route_key(row),
                number(Some(row.count)),
                milliseconds(row.avg_ms)
            )
        })
        .collect::<Vec<_>>();
    if !held.is_empty() {
        let _ = writeln!(out, "  polling  {}", held.join("; "));
    }
    if let Some(files) = brief
        .http_static_files
        .as_ref()
        .filter(|files| files.count > 0.0)
    {
        let _ = writeln!(
            out,
            "  static   {} ({}% of requests)",
            number(Some(files.count)),
            files.share_percent
        );
    }
}

/// digestを表示用に短くする：`INSERT ride_statuses`、`SELECT rides by chair_id`、`COMMIT`。
fn shorten_sql(digest: &str) -> String {
    let words = digest
        .replace('`', "")
        .split_whitespace()
        .map(str::to_owned)
        .collect::<Vec<_>>();
    let upper = words
        .iter()
        .map(|word| word.to_uppercase())
        .collect::<Vec<_>>();
    let after = |keyword: &str| {
        upper
            .iter()
            .position(|word| word == keyword)
            .and_then(|index| words.get(index + 1))
            .map(|word| {
                word.trim_matches(|c: char| !(c.is_alphanumeric() || c == '_' || c == '.'))
                    .to_owned()
            })
            .filter(|word| !word.is_empty())
    };
    let Some(verb) = upper.first() else {
        return String::new();
    };
    let table = match verb.as_str() {
        "SELECT" | "DELETE" => after("FROM"),
        "INSERT" | "REPLACE" => after("INTO"),
        "UPDATE" => words.get(1).cloned(),
        _ => None,
    };
    match table {
        Some(table) => {
            let mut text = format!("{verb} {table}");
            if verb == "SELECT"
                && let Some(column) = after("WHERE")
            {
                let _ = write!(text, " by {column}");
            }
            text
        }
        None => shorten(&words.join(" "), 30),
    }
}

fn sql(out: &mut String, inputs: &Inputs) {
    let database = &inputs.run.brief.database;
    let rows = database.items.iter().take(TOP).collect::<Vec<_>>();
    if rows.is_empty() {
        return;
    }
    let window = database
        .window
        .as_deref()
        .map(|window| format!(" ({window})"))
        .unwrap_or_default();
    let items = rows
        .iter()
        .map(|row| {
            format!(
                "{} {}×{}ms ({})",
                shorten_sql(&row.digest),
                number(Some(row.calls)),
                milliseconds(row.avg_ms),
                seconds(row.total_ms)
            )
        })
        .collect::<Vec<_>>();
    let _ = writeln!(out, "sql {}{window}  {}", rows[0].node, items.join(", "));
}

fn app(out: &mut String, inputs: &Inputs) {
    let brief = &inputs.run.brief;
    let locks = brief.app_locks.items.iter().take(TOP).collect::<Vec<_>>();
    let calls = &brief.app_calls.items;
    if locks.is_empty() && calls.is_empty() {
        return;
    }
    let node = locks
        .first()
        .map(|lock| lock.node.as_str())
        .or_else(|| calls.first().map(|call| call.node.as_str()))
        .unwrap_or_default();
    let mut lines = Vec::new();
    if !locks.is_empty() {
        lines.push(format!(
            "lock wait {}",
            locks
                .iter()
                .map(|lock| {
                    format!(
                        "{} {} (max {})",
                        lock.lock,
                        seconds(lock.wait_ms),
                        lock.wait_max_ms.map(seconds).unwrap_or_else(|| "-".into())
                    )
                })
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    // 呼び先ごとに、全ての結果を合わせた試行数と時間から割合と平均を出す。
    let mut targets = BTreeMap::<&str, (f64, f64, Vec<(&str, f64)>)>::new();
    for call in calls {
        let target = targets.entry(call.target.as_str()).or_default();
        target.0 += call.count;
        target.1 += call.total_ms;
        target.2.push((call.outcome.as_str(), call.count));
    }
    let mut targets = targets.into_iter().collect::<Vec<_>>();
    targets.sort_by(|a, b| b.1.1.total_cmp(&a.1.1));
    for (target, (count, total_ms, mut outcomes)) in targets.into_iter().take(TOP) {
        outcomes.sort_by(|a, b| b.1.total_cmp(&a.1));
        let shares = outcomes
            .iter()
            .take(4)
            .map(|(outcome, value)| {
                format!(
                    "{outcome} {:.0}%",
                    if count > 0.0 {
                        value / count * 100.0
                    } else {
                        0.0
                    }
                )
            })
            .collect::<Vec<_>>();
        let more = outcomes.len().saturating_sub(shares.len());
        lines.push(format!(
            "calls {target} {}: {}{} (avg {}ms)",
            number(Some(count)),
            shares.join(", "),
            if more > 0 {
                format!(", +{more} more")
            } else {
                String::new()
            },
            milliseconds((count > 0.0).then(|| total_ms / count))
        ));
    }
    let _ = writeln!(out, "app {node}  {}", lines.join("\n         "));
}

fn edge(out: &mut String, inputs: &Inputs) {
    let brief = &inputs.run.brief;
    let mut parts = Vec::new();
    let mut node = None;
    if let Some(client) = brief.clients.items.first() {
        node = Some(client.node.clone());
        parts.push(format!(
            "conns avg {}, new {}/s",
            number(client.connections_in_use_avg),
            client
                .connections_opened_per_second
                .map(|value| format!("{value:.0}"))
                .unwrap_or_else(|| "-".into())
        ));
    }
    let mut upstreams = brief.upstreams.items.iter().collect::<Vec<_>>();
    upstreams.sort_by(|a, b| b.requests.total_cmp(&a.requests));
    for upstream in upstreams.into_iter().take(2) {
        node.get_or_insert_with(|| upstream.node.clone());
        parts.push(format!(
            "upstream {} connect p95 {}ms, header p95 {}ms",
            upstream.upstream,
            milliseconds(upstream.connect_p95_ms),
            milliseconds(upstream.header_p95_ms)
        ));
    }
    if let Some(node) = node {
        let _ = writeln!(out, "edge {node}  {}", parts.join("; "));
    }
}

fn go(out: &mut String, inputs: &Inputs) {
    let brief = &inputs.run.brief;
    let functions = brief.go_cpu_app.items.iter().take(TOP).collect::<Vec<_>>();
    let classes = brief.go_classes.items.iter().take(TOP).collect::<Vec<_>>();
    if let Some(first) = functions.first() {
        let _ = writeln!(
            out,
            "go {}  cpu {}",
            first.node,
            functions
                .iter()
                .map(|row| format!(
                    "{} {:.0}%{}",
                    row.function,
                    row.percent,
                    row.cores
                        .map(|cores| format!(" ({cores:.2} cores)"))
                        .unwrap_or_default()
                ))
                .collect::<Vec<_>>()
                .join(", ")
        );
    }
    if let Some(first) = classes.first() {
        let _ = writeln!(
            out,
            "go {}  classes {}",
            first.node,
            classes
                .iter()
                .map(|row| format!("{} {:.0}%", row.class, row.percent))
                .collect::<Vec<_>>()
                .join(", ")
        );
    }
}

/// あったときだけ出す行：計測の欠け、負荷区間の代わりにベンチ全体を集計したこと、logのエラー、
/// 当たった上限。
fn issues(out: &mut String, inputs: &Inputs) {
    let brief = &inputs.run.brief;
    let coverage = &brief.coverage_issues.items;
    if !coverage.is_empty() {
        let mut groups = coverage
            .iter()
            .take(TOP)
            .map(|group| {
                let nodes = group
                    .nodes
                    .iter()
                    .filter(|node| node.as_str() != "-")
                    .cloned()
                    .collect::<Vec<_>>();
                let mut text = if group.collector == "-" {
                    format!("{} {}", group.section, group.status)
                } else {
                    format!("{}: {} {}", group.section, group.collector, group.status)
                };
                if !nodes.is_empty() {
                    let _ = write!(text, " on {}", nodes.join(", "));
                }
                text
            })
            .collect::<Vec<_>>();
        if coverage.len() > TOP {
            groups.push(format!("+{} more", coverage.len() - TOP));
        }
        let _ = writeln!(out, "coverage {}", groups.join("; "));
    }
    if brief.hosts.window.as_deref() == Some("whole") {
        let _ = writeln!(
            out,
            "window   whole benchmark including initialize (no initialize boundary)"
        );
    }
    if let Some(log) = brief.logs.items.iter().max_by_key(|log| log.count) {
        let _ = writeln!(
            out,
            "logs     {} {} {}× \"{}\"",
            log.node,
            log.source,
            thousands(log.count as f64),
            sample(&log.example)
        );
    }
    for limit in brief
        .limits
        .items
        .iter()
        .filter(|limit| limit.evidence.is_some())
        .take(TOP)
    {
        let _ = writeln!(
            out,
            "limit    {} {}{}: {}",
            limit.node,
            limit.config_key,
            limit
                .value
                .map(|value| format!(" {}", number(Some(value))))
                .unwrap_or_default(),
            limit.evidence.as_deref().unwrap_or_default()
        );
    }
}

/// `+5.2%`。比べられなければ`None`。
fn change(value: Option<f64>, base: Option<f64>) -> Option<String> {
    let (value, base) = (value?, base?);
    (base != 0.0).then(|| format!("{:+.1}%", (value - base) / base * 100.0))
}

fn number(value: Option<f64>) -> String {
    match value {
        Some(value) if value.fract() == 0.0 || value.abs() >= 100.0 => thousands(value),
        Some(value) => format!("{value:.1}"),
        None => "-".into(),
    }
}

/// msの値。1000以上と整数の値は整数、それ以外は小数1桁。
fn milliseconds(value: Option<f64>) -> String {
    match value {
        Some(value) if value.abs() >= 1000.0 || value.fract() == 0.0 => thousands(value),
        Some(value) => format!("{value:.1}"),
        None => "-".into(),
    }
}

/// msの値を秒で。
fn seconds(ms: f64) -> String {
    let value = ms / 1000.0;
    if value.abs() >= 100.0 {
        format!("{}s", thousands(value))
    } else if value.abs() >= 1.0 {
        format!("{value:.1}s")
    } else if value.abs() >= 0.01 {
        format!("{value:.2}s")
    } else {
        format!("{ms:.0}ms")
    }
}

fn cores(value: Option<f64>) -> String {
    value.map_or("-".into(), |value| format!("{value:.2}"))
}

fn percent(value: Option<f64>) -> String {
    value.map_or("-".into(), |value| format!("{value:.0}"))
}

fn sample(text: &str) -> String {
    let text = text.split_whitespace().collect::<Vec<_>>().join(" ");
    crate::model::excerpt(&text, SAMPLE_CHARS).0
}

fn shorten(text: &str, chars: usize) -> String {
    crate::model::excerpt(text, chars.saturating_sub(1)).0
}

