use super::*;
use std::io::{BufRead, BufReader};

/// 1回ごとに数字の変わるベンチ。`count`のfileでrunの回数を数え、scoreは回数×1000。
/// 1回目と2回目で、HTTPの合計時間の順位、警告の件数、状態ログの件数が変わる。
fn project() -> tempfile::TempDir {
    let project = tempdir().unwrap();
    let config_dir = project.path().join(".isuscope");
    fs::create_dir_all(&config_dir).unwrap();
    fs::write(
        config_dir.join("config.toml"),
        r#"
[benchmark]
mode = "command"
command = ["sh", "-c", """
n=$(cat count 2>/dev/null || echo 0); n=$((n+1)); echo $n > count
printf '%s\n' '{"type":"isuscope.event","name":"initialize-started"}'
printf '%s\n' '{"type":"isuscope.event","name":"initialize-finished"}'
sleep 1
printf '{"type":"isuscope.result","score":%d,"pass":true}\n' $((n*1000))
"""]

# 警告の実例は5件までしか残らない。件数はmetricで数える。
[[benchmark.parsers]]
name = "contest-output"
command = ["sh", "-c", """
n=$(cat count)
if [ "$n" = 1 ]; then warnings=3; else warnings=8; fi
i=0
while [ $i -lt $warnings ]; do
  printf '{"type":"message","kind":"warning","category":"CODE=30","text":"chair %d is on a ride (CODE=30)"}\n' $i
  i=$((i+1))
done
printf '{"type":"metric","name":"benchmark.warnings","value":%d,"unit":"lines","labels":{"category":"CODE=30"}}\n' $warnings
printf '{"type":"metric","name":"benchmark.warnings_total","value":%d,"unit":"lines"}\n' $warnings
if [ "$n" != 1 ]; then
  printf '%s\n' '{"type":"message","kind":"warning","category":"CODE=24","text":"sales are larger than expected (CODE=24)"}'
  printf '%s\n' '{"type":"metric","name":"benchmark.warnings","value":1,"unit":"lines","labels":{"category":"CODE=24"}}'
fi
printf '%s\n' '{"type":"metric","name":"benchmark.errors_total","value":0,"unit":"lines"}'
"""]

[brief]
polling_routes = ["GET /poll"]

[[brief.counts]]
label = "ride created"
kind = "ride"

[[brief.counts]]
label = "ride COMPLETED"
kind = "ride"
state = "COMPLETED"

# 1回目は/aが、2回目は/bが合計時間の1位。/pollは長く開いたままの要求。
[[collectors]]
name = "evidence"
phase = "after"
transport = "local"
command = ["sh", "-c", """
n=$(cat count)
if [ "$n" = 1 ]; then a=9; b=1; else a=2; b=8; fi
route() {
  printf '{"type":"metric","name":"http.requests","value":%s,"unit":"requests","labels":{"node":"app1","method":"GET","route":"%s"}}\n' "$2" "$1"
  printf '{"type":"metric","name":"http.request_duration_sum","value":%s,"unit":"ms","labels":{"node":"app1","method":"GET","route":"%s"}}\n' "$(($2*$3))" "$1"
  printf '{"type":"metric","name":"http.request_duration_mean","value":%s,"unit":"ms","labels":{"node":"app1","method":"GET","route":"%s"}}\n' "$3" "$1"
}
route /a 1000 $a
route /b 1000 $b
route /poll 20 5000
state() {
  printf '{"type":"metric","name":"state.transitions","value":%s,"unit":"transitions","labels":{"node":"app3","kind":"ride","from":"%s","to":"%s","window":"load"}}\n' "$3" "$1" "$2"
}
state - MATCHING $((n*100))
state ARRIVED COMPLETED $((n*80))
at() { awk -v origin='{load_started_at}' -v offset="$1" 'BEGIN { printf "%.3f", origin + offset }'; }
call() { printf '{"type":"metric","name":"app.call.%s","value":%s,"unit":"x","labels":{"node":"app3","target":"payment","outcome":"%s"},"timestamp":%s}\n' "$1" "$2" "$3" "$(at 0.5)"; }
